import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 35 · Christmas recipe: peanut butter blossoms (Google Trends 3/11: peanut rising topic, easy christmas cookies)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, there's one Christmas cookie that every single grandmother in America has made. The little round peanut butter cookie, rolled in sugar, with a chocolate kiss pressed right in the middle. Peanut butter blossoms. On every cookie tray at every church party since I was a young mother. And every December, somebody tells me theirs came out flat, dry, or cracked to pieces.""",
   "peanut butter blossom cookies tray", "EVERY GRANDMOTHER")
sc("""So tonight I'm giving you my peanut butter blossoms. Soft and chewy, thick and round, with the kiss sitting pretty in the middle and no cracks. Every step, and the four mistakes that make them go flat. And stay with me, because the last mistake is about the chocolate, and almost everybody does it at the wrong moment.""",
   "soft peanut butter cookies chocolate kiss", "THICK AND ROUND")

ch("A prize-winning cookie")
sc("""This cookie is younger than me, believe it or not. It came from a baking contest in the late nineteen fifties, the big national one sponsored by a flour company. A woman from Ohio, Freda Smith, entered a peanut butter cookie with a chocolate candy pressed on top. She didn't win first prize. But her cookie became more famous than the winner.""",
   "1950s baking contest women aprons", "MORE FAMOUS THAN THE WINNER")
sc("""The first time I made them was nineteen sixty-four, for my son's first Christmas. I saw the recipe in a magazine at the beauty parlor and tore it out when nobody was looking. I've confessed that sin to my pastor. I've made them every December since, sixty-two Christmases, and that torn magazine page is still in my recipe box, held together with tape.""",
   "torn magazine recipe page vintage", "I CONFESSED THAT SIN")
sc("""My husband used to say they were the only cookie where you got dessert on top of your dessert. And the grandchildren fight over who gets to unwrap the chocolate kisses. Last year I had five of them at the kitchen table, unwrapping and eating, and by the end I had forty-eight cookies and only thirty-one kisses. In a minute I'll tell you how to keep the little helpers away from them.""",
   "children unwrapping chocolate candies", "ONLY THIRTY-ONE KISSES")

ch("What you need")
sc("""Here's what you need, honey, for about four dozen. Half a cup of butter, softened. Half a cup of creamy peanut butter. Half a cup of white sugar, plus more for rolling. Half a cup of packed brown sugar. One egg. Two tablespoons of milk. One teaspoon of vanilla. One and three quarter cups of flour. One teaspoon of baking soda. Half a teaspoon of salt. And about forty-eight chocolate kisses, unwrapped.""",
   "peanut butter butter sugar flour bowls", "ABOUT FOUR DOZEN")
sc("""Now, the peanut butter. Use the regular creamy kind from the jar, the one you stir with no oil on top. The natural peanut butter, where the oil floats up, sounds healthier, but it makes the cookies spread and turn greasy and crumbly. This is mistake number one. Save the natural kind for your toast.""",
   "jar of creamy peanut butter spoon", "NOT THE NATURAL KIND")

sc("""And measure the flour right, honey, because too much flour is what makes these dry and crumbly. Don't scoop the cup into the bag. Spoon the flour into the measuring cup, and level it off with the back of a knife. Scooping packs in up to a quarter cup extra, and with a dough this rich, that quarter cup turns a soft cookie into a dry one.""",
   "spooning flour measuring cup level", "SPOON AND LEVEL")

ch("Step by step")
sc("""Step one. Beat the butter, peanut butter, and both sugars together until smooth and creamy, about two minutes. Then beat in the egg, the milk and the vanilla. In another bowl, stir the flour, baking soda and salt. Add it to the peanut butter mixture slowly, mixing just until there's no dry flour left. The dough will be soft and a little sticky.""",
   "mixing peanut butter cookie dough", "SOFT AND A LITTLE STICKY")
sc("""Step two, and this is where most people go wrong. Cover the bowl and chill the dough in the icebox for at least one hour. Mistake number two is skipping this. Warm peanut butter dough spreads in the oven into thin, flat discs, and then the kiss has nowhere to sit. Cold dough holds its round shape and bakes up thick and puffy.""",
   "bowl covered refrigerator dough", "CHILL ONE HOUR")
sc("""Step three. Heat the oven to three hundred seventy-five. Roll the cold dough into balls about one inch across, about a tablespoon each. Then roll each ball in a little bowl of white sugar until it's coated all over. The sugar makes that pretty sparkly crust that crackles a little on top. Set them two inches apart on a parchment-lined baking sheet.""",
   "rolling cookie dough balls in sugar", "ROLL THEM IN SUGAR")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. Now, step four. Bake them for eight to ten minutes, just until they're puffed and the tops are starting to crack and the edges are barely golden. Mistake number three is baking them too long. If they look done in the oven, they'll be dry and hard by morning.""",
   "peanut butter cookies baking oven", "BARELY GOLDEN")

sc("""How do you tell when they're done? The tops should have little cracks, like dry earth, and look just barely set. The middles should still look a tiny bit soft and shiny. Take one out, and press the edge gently. If it holds, they're ready. They keep baking on the hot pan for a minute or two after they come out, so trust me and take them out early.""",
   "cookie tops cracked baking sheet", "LIKE DRY EARTH")

ch("The kiss")
sc("""So far, regular peanut butter, chill the dough, roll in sugar, and bake them just until puffed. Now the kiss, and the fourth mistake I promised you. Most people press the chocolate kiss in right away, the second the pan comes out of the oven. And the cookie cracks all the way around, like a broken plate, because it's still too soft and puffed.""",
   "cracked cookie chocolate kiss", "LIKE A BROKEN PLATE")
sc("""Here's the trick. Let the cookies sit on the pan for two or three minutes first. Just long enough that the outside sets a little, but they're still warm and soft in the middle. Then press a kiss straight down into the center of each one, firmly, so the cookie crinkles around it like a flower opening. That's why they're called blossoms.""",
   "pressing chocolate kiss into cookie", "LIKE A FLOWER OPENING")
sc("""And the other half of the kiss mistake. The chocolate melts from the warm cookie, and if you move the cookies or stack them, the kisses smear and lose their point. So once the kisses are in, move the whole sheet of parchment to the counter, and then put the whole tray in the icebox for fifteen minutes. The chocolate sets back up firm, with that perfect little point on top.""",
   "cookies cooling chocolate kisses set", "THE PERFECT LITTLE POINT")
sc("""And here's how I keep the little helpers away from the kisses, like I promised. Unwrap them yourself, the night before, and put them in a covered bowl in the icebox, out of sight. Cold kisses also hold their shape better when you press them in. Then give the children their own small bowl of kisses to unwrap and eat, so they leave yours alone.""",
   "bowl of unwrapped chocolate kisses", "OUT OF SIGHT")

ch("Christmas variations")
sc("""For Christmas, change the topping and you have a whole new cookie. Press in a peppermint kiss, or a caramel-filled one. Or roll the balls in red and green sugar instead of white. Or use a little piece of a dark chocolate bar. My grandson likes a whole peanut butter cup pressed in the middle. That's not a blossom anymore, honey. That's a dare.""",
   "Christmas cookies red green sugar", "THAT'S A DARE")
sc("""And if somebody in your family can't have peanuts, sweetheart, make the same cookie with sunflower seed butter instead. It bakes almost exactly the same. Be careful, because sunflower butter can turn a little green inside when it bakes with baking soda. It's perfectly safe, it's just chemistry. Use a little less baking soda, and tell the children it's a Christmas elf cookie.""",
   "sunflower seed butter jar cookies", "A CHRISTMAS ELF COOKIE")

ch("Keeping and giving")
sc("""They keep a week in a tin, with wax paper between the layers so the kisses don't stick. Don't stack them while they're warm. And the dough freezes beautifully. Roll it into balls, roll them in sugar, freeze them on a tray, then put them in a bag. On Christmas Eve, bake them straight from the freezer, adding one or two minutes.""",
   "cookie tin layers wax paper", "STRAIGHT FROM THE FREEZER")
sc("""And they're the perfect cookie for the cookie exchange. Everybody recognizes them, everybody loves them, and they look like Christmas on a plate. At my church's cookie swap, there are always three trays of peanut butter blossoms. Mine is always the one that runs out first. I'm not proud, honey. Well, I'm a little proud.""",
   "church cookie exchange table trays", "I'M A LITTLE PROUD")
sc("""And here's a good gift. A jar of the dry ingredients, flour, sugars, baking soda and salt, layered in a big mason jar, with a bag of kisses on top and the recipe on a tag. People just add the butter, peanut butter, egg and milk. I give them to the young mothers at church, and they tell me it's the first cookie their children ever made.""",
   "cookie mix mason jar gift tag", "THEIR FIRST COOKIE")

ch("Grandma's kitchen")
sc("""So one more time. Regular creamy peanut butter, not natural. Chill the dough an hour. Roll in sugar. Eight to ten minutes, just puffed. Let them rest two or three minutes before you press in the kiss, then chill the tray so the chocolate sets with a point. That's how you get peanut butter blossoms that are thick and soft and never cracked.""",
   "peanut butter blossoms Christmas plate", "THICK AND SOFT")
sc("""Tell me in the comments, sweetheart. Who made peanut butter blossoms in your family? And do you eat the kiss first, or the cookie? The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "plate of cookies Christmas evening", "KISS FIRST OR COOKIE?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma35", "Peanut Butter Blossoms EVERYONE's Grandma Made (Why Yours Go FLAT)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Peanut Butter Blossoms, entered by Freda Smith of Gibsonburg, Ohio, in the Pillsbury Bake-Off in the late 1950s.",
      "Recipe as written by Grandma Ruth: 1/2 cup butter, 1/2 cup creamy peanut butter, 1/2 cup sugar, 1/2 cup brown sugar, 1 egg, 2 tbsp milk, 1 tsp vanilla, 1 3/4 cups flour, 1 tsp baking soda, 1/2 tsp salt; chill 1 hour; 375 F for 8 to 10 minutes; kiss pressed in after 2 to 3 minutes.",
      "Sunflower seed butter can turn green when baked with baking soda (chlorogenic acid), which is harmless."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
